UPDATE lessons SET title='Year 3, Week 13, Lesson 1: Free verse and mood', data=json_patch(data,'{"child_mission":"Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWho is the audience, and what is the request, in \"Families should walk to school on Fridays to reduce parking crowding\"?\n\nFEEDBACK\nAudience: families. Request: walk to school on Fridays. Reason: reduce parking crowding.\n\nCHECK\nA persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nFind or write a short persuasive paragraph about a school or home issue. Identify audience, request and two reasons. Explain whether the reasons suit that audience.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-RECOM-01","EN2-UARL-01"],"parent_notes":"Parent: Marking guidance for the independent task: Find or write a short persuasive paragraph about a school or home issue. Identify audience, request and two reasons. Explain whether the reasons suit that audience. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding. Reasoning: I used persuasion by attending to audience and explain why it matters rather than copying the worked model.\n\nParent: Written model 2: Common error: A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Correction: Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding. Why: the correction restores accurate use of persuasion.\n\nParent: Likely misconception: A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating persuasion on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with persuasion, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding. This matches the lesson skill for persuasion.","options":["Copy the worked example and call it independent work.","Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding.","A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept.","Ignore the task and invent an unrelated answer."],"question":"Who is the audience, and what is the request, in \"Families should walk to school on Fridays to reduce parking crowding\"?","type":"multiple_choice"},{"correct_index":3,"explanation":"A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience.","Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding.","Careful use of audience and explain why it matters with clear evidence.","A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept."],"question":"Which statement is a common mistake when practising persuasion?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and named audience and explain why it matters, not by copying the model.","options":["Choose randomly because any option could be right.","Treat a missing detail as a proven fact.","Apply the idea with new evidence and name the audience and explain why it matters used.","Repeat the worked example wording with no new evidence."],"question":"A learner is practising persuasion. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":0,"explanation":"The skill is shown by quoting or pointing to wording that carries persuasion.","options":["Point to exact words in the sentence that show persuasion and say what they do.","Ignore the sentence and invent a more exciting event.","Say the writing is good without naming any words.","A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept."],"question":"Read: \"At dawn, Mina whispered to her goat as frost glittered on the fence.\" Which choice best uses persuasion from this lesson?","type":"multiple_choice"},{"correct_index":3,"explanation":"The correct statement applies the language skill; the others miss the evidence.","options":["A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept.","Ignore the task and invent an unrelated answer.","Copy the worked example and call it independent work.","Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding."],"question":"Which statement correctly applies the lesson idea about persuasion?","type":"multiple_choice"},{"correct_index":0,"explanation":"Start from a specific textual clue, then explain its effect.","options":["Locate a specific word, phrase or structural clue before deciding.","Guess from the title alone with no textual clue.","Copy a model sentence from another story unchanged.","Treat a missing detail as a proven fact."],"question":"In a new text, what should you do first to practise audience and explain why it matters?","type":"multiple_choice"},{"correct_index":2,"explanation":"Repair means fixing meaning or evidence, not padding.","options":["Make the answer longer while keeping the same mistake.","Delete the evidence that disagreed with your first guess.","Change the inaccurate idea or missing evidence, not only the length.","Add adjectives without fixing the wrong idea."],"question":"Which revision actually repairs meaning?","type":"multiple_choice"},{"correct_index":3,"explanation":"Transfer needs fresh material with an explained language choice.","options":["Retype the worked model as the final answer.","Change fonts and claim the work is new.","A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept.","Use a fresh sentence or text and explain one precise choice about persuasion."],"question":"Which response shows transfer of persuasion to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating persuasion on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding. Reasoning: I used persuasion by attending to audience and explain why it matters rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with persuasion, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Correction: Audience: families. Request: walk to school on Fridays. Reason: reduce parking crowding. Why: the correction restores accurate use of persuasion.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent task and reflection, with explanations where requested.","review_status":"unreviewed","seed_key":"s2-eng-y3-w13-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; verify content points before acceptance.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise persuasion.","Read the mission before you start writing or speaking.","Keep the audience and purpose in mind as you work."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reason with the feedback.","Adjust anything that does not match the evidence."],"learn":["Study how the first demonstration is built.","Point to the wording that carries the meaning.","Then explain the choice without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore the example.","Prefer evidence over wording that merely sounds clever."],"submit":["Check that your response and reason are both present.","Proofread names, sequence and punctuation.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact word or action before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and underline one useful detail.","Say what that detail helps a reader understand.","A vague compliment is weaker than quoted evidence."],"teach2":["Compare a weak attempt with a stronger revision.","Change meaning or accuracy, not only length.","Name the mistake you are repairing."],"teach3":["Choose a fresh topic that still uses the same skill.","Explain one decision in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include an original response and a short reason.","Save work that shows the skill on new content."]},"subject":"English","success_criteria":["I can use persuasion with a specific example from this lesson.","I can identify audience and explain why it matters.","I can practise reason independently on a new prompt.","I can notice purpose needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience. A supported explanation follows the actual words and purpose of the task. Apply the lesson idea with evidence.","options":["Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience.","A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation."],"question":"Which choice best shows accurate use of this idea about persuasion?","type":"multiple_choice"},"example":"WORKED MODEL\n\"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who care about animals.\n\nTRY FIRST\nWho is the audience, and what is the request, in \"Families should walk to school on Fridays to reduce parking crowding\"?\n\nFEEDBACK\nAudience: families. Request: walk to school on Fridays. Reason: reduce parking crowding.","explain":"Persuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Correct the meaning, not just the appearance.","title":"Understand and model","visual":[{"alt":"Persuasive request linked to a wildlife reason.","caption":"Name the ask and a reason the audience may care about.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Request</text><text x=\"28\" y=\"78\">join the clean-up</text><text x=\"358\" y=\"42\">Reason</text><text x=\"358\" y=\"78\">protect creek wildlife</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or actions that carry the meaning before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: \"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who c Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which detail matters most.\nJuno: Name the exact words or actions that carry the meaning before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: \"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who c Then write your own attempt."}}]},{"check":{"correct_index":2,"explanation":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader. A supported explanation follows the actual words and purpose of the task. Apply the lesson idea with evidence.","options":["An answer copied without understanding.","A guess with no explanation.","Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.","A claim unrelated to the text."],"question":"Which choice best shows accurate use of this idea about persuasion?","type":"multiple_choice"},"example":"WORKED MODEL\n\"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who care about animals. Think about how this word or relationship creates meaning.\n\nTRY FIRST\nUnderline or quote one precise detail in the model and explain its effect.\n\nFEEDBACK\nThe most useful evidence is a specific choice in the example, followed by an explanation of the effect on meaning.","explain":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Saying a choice is good without naming the actual detail does not show understanding. Correct the meaning, not just the appearance.","title":"Explain the evidence","visual":[{"alt":"Audience families with purpose to walk on Fridays.","caption":"Reasons should suit the people being persuaded.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Audience</text><text x=\"28\" y=\"78\">families</text><text x=\"358\" y=\"42\">Purpose</text><text x=\"358\" y=\"78\">walk on Fridays</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error. A supported explanation follows the actual words and purpose of the task. Apply the lesson idea with evidence.","options":["A guess with no explanation.","Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.","A claim unrelated to the text.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about persuasion?","type":"multiple_choice"},"example":"WORKED MODEL\nA persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Here is a more productive model: \"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who care about animals.\n\nTRY FIRST\nDescribe why the warned-against approach would weaken your work, then write a corrected version.\n\nFEEDBACK\nAudience: families. Request: walk to school on Fridays. Reason: reduce parking crowding.","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"A superficial change in length or appearance does not repair meaning. A persuasive text is not only shouting; it needs a clear ask and reasons the audience may accept. Correct the meaning, not just the appearance.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity. A supported explanation follows the actual words and purpose of the task. Apply the lesson idea with evidence.","options":["Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.","A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation."],"question":"Which choice best shows accurate use of this idea about persuasion?","type":"multiple_choice"},"example":"WORKED MODEL\nPersuasive texts try to influence an audience''s ideas or actions using clear reasons suited to that audience. Now choose different people, facts or text to show you can transfer the idea.\n\nTRY FIRST\nMake one fresh example demonstrating the skill and explain your main choice.\n\nFEEDBACK\nThe new example should meet the same purpose as the model, but contain original material.","explain":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new content. Correct the meaning, not just the appearance.","title":"Transfer to an independent example"}],"title":"Year 3, Week 13, Lesson 1: Free verse and mood","unit_number":3,"unit_title":"Poetry: rhyme, rhythm and imagery","week":13,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\n\"Please join the clean-up because litter harms creek wildlife\" names an action and a reason that matters to people who care about animals.\n\nExplain what makes this example accurate and effective, identifying its specific wording.","worked_visuals":[{"alt":"Persuasive request linked to a wildlife reason.","caption":"Name the ask and a reason the audience may care about.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Request</text><text x=\"28\" y=\"78\">join the clean-up</text><text x=\"358\" y=\"42\">Reason</text><text x=\"358\" y=\"78\">protect creek wildlife</text></g></svg>"},{"alt":"Audience families with purpose to walk on Fridays.","caption":"Reasons should suit the people being persuaded.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Audience</text><text x=\"28\" y=\"78\">families</text><text x=\"358\" y=\"42\">Purpose</text><text x=\"358\" y=\"78\">walk on Fridays</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w13-l1' AND family_id IS NULL;
